mapper.select:
select
    fc.*,
    su.nickname as owner_nickname,
    su.username as owner_username
from sys_file_center fc
    left join sys_user su on fc.user_id = su.id


        and fc.file_name like concat('%', #{q.fileName}, '%')


        and fc.business_type = #{q.businessType}


        and fc.file_status = #{q.fileStatus}


        and fc.create_time >= #{q.startTime}


        and fc.create_time <= #{q.endTime}



        and fc.file_status != 4





            and fc.user_id = #{q.userId}
            and fc.file_source != 4


            and fc.file_source = 2

                and exists (
                    select 1 from sys_dept_user d1
                    inner join sys_dept_user d2 on d1.dept_id = d2.dept_id
                    where d1.user_id = fc.user_id and d2.user_id = #{q.userId}
                )



            and fc.file_source = 3

                and exists (
                    select 1 from sys_user_role r1
                    inner join sys_user_role r2 on r1.role_id = r2.role_id
                    where r1.user_id = fc.user_id and r2.user_id = #{q.userId}
                )



            and fc.file_source = 4

                and (
                    fc.user_id = #{q.userId}
                    or exists (
                        select 1 from sys_dept_user d1
                        inner join sys_dept_user d2 on d1.dept_id = d2.dept_id
                        where d1.user_id = fc.user_id and d2.user_id = #{q.userId}
                    )
                    or exists (
                        select 1 from sys_user_role r1
                        inner join sys_user_role r2 on r1.role_id = r2.role_id
                        where r1.user_id = fc.user_id and r2.user_id = #{q.userId}
                    )
                )




order by fc.create_time desc

select count(1) from sys_dept_user d1
inner join sys_dept_user d2 on d1.dept_id = d2.dept_id
where d1.user_id = #{fileOwnerId} and d2.user_id = #{userId}

select count(1) from sys_user_role r1
inner join sys_user_role r2 on r1.role_id = r2.role_id
where r1.user_id = #{fileOwnerId} and r2.user_id = #{userId}
